import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"即時答案與關鍵詞功能","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/instant-answers.md","filePath":"zh-HK/user-guide/instant-answers.md","lastUpdated":1785993908000}'),s={name:"zh-HK/user-guide/instant-answers.md"};function r(n,t,c,i,l,h){return a(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="即時答案與關鍵詞功能" tabindex="-1">即時答案與關鍵詞功能 <a class="header-anchor" href="#即時答案與關鍵詞功能" aria-label="Permalink to &quot;即時答案與關鍵詞功能&quot;">​</a></h1><p>有些結果會在你打字的同時立刻出現，不需要等檔案搜尋完成——要麼是始終生效的，要麼是需要你先輸入一個簡短的關鍵詞、再接你真正想查的內容(這樣像&quot;搜尋瀏覽器歷史記錄&quot;這類分量較重的功能，就不會在你打每一個跟它無關的字元時都來搶注意力)。大多數需要關鍵詞的功能，其關鍵詞都可以在<strong>設定 → 插件 → 配置</strong> 裏自行修改。</p><h2 id="始終生效" tabindex="-1">始終生效 <a class="header-anchor" href="#始終生效" aria-label="Permalink to &quot;始終生效&quot;">​</a></h2><p>這些不需要關鍵詞——只要你輸入的內容匹配它們的模式，就會立刻觸發。</p><h3 id="計算器" tabindex="-1">計算器 <a class="header-anchor" href="#計算器" aria-label="Permalink to &quot;計算器&quot;">​</a></h3><p>直接輸入數學表達式，結果會實時顯示出來，按 <strong>Enter</strong> 把結果複製到剪貼簿:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span></code></pre></div><p>也支援顯式的進制轉換:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span></code></pre></div><h3 id="環境變量" tabindex="-1">環境變量 <a class="header-anchor" href="#環境變量" aria-label="Permalink to &quot;環境變量&quot;">​</a></h3><ul><li><code>%NAME%</code> 展開某個具體的變量(包括像 <code>%PATH%</code> 這種多路徑變量，會按路徑逐條拆開列出)。</li><li><code>%partial</code> 模糊列出所有名稱裏包含 <code>partial</code> 的變量。</li></ul><h3 id="運行命令" tabindex="-1">運行命令 <a class="header-anchor" href="#運行命令" aria-label="Permalink to &quot;運行命令&quot;">​</a></h3><ul><li><code>#&lt;命令&gt;</code> 打開命令提示字元視窗，<strong>以系統管理員權限</strong>運行 <code>&lt;命令&gt;</code>。</li><li><code>$&lt;命令&gt;</code> 打開命令提示字元視窗，以普通權限運行 <code>&lt;命令&gt;</code>。</li></ul><h3 id="裸網址" tabindex="-1">裸網址 <a class="header-anchor" href="#裸網址" aria-label="Permalink to &quot;裸網址&quot;">​</a></h3><p>直接輸入或貼上一個 <code>http://</code>/<code>https://</code> 地址，Lertaro 會提示直接打開它。</p><h2 id="關鍵詞觸發-內置插件-前綴可配置" tabindex="-1">關鍵詞觸發(內置插件，前綴可配置) <a class="header-anchor" href="#關鍵詞觸發-內置插件-前綴可配置" aria-label="Permalink to &quot;關鍵詞觸發(內置插件，前綴可配置)&quot;">​</a></h2><p>輸入關鍵詞、一個空格，然後接你真正的查詢內容。每個關鍵詞都有一個預設的簡短前綴，如果它和你常打的內容衝突，也可以在對應插件自己的<strong>配置</strong>對話方塊裏單獨修改。</p><table tabindex="0"><thead><tr><th>關鍵詞(預設)</th><th>插件</th><th>搜尋的內容</th></tr></thead><tbody><tr><td><code>ps</code></td><td>處理程序管理</td><td>按名稱、PID 或視窗標題搜尋正在運行的處理程序(也支援模糊/拼音匹配)——選中一個即可結束它。</td></tr><tr><td><code>win</code></td><td>視窗切換器</td><td>當前打開的、可切換的視窗(和 Alt+Tab 顯示的是同一批)，按標題、處理程序名或 PID 搜尋——選中即可切換到該視窗。</td></tr><tr><td><code>bm</code></td><td>瀏覽器資料</td><td>搜尋你在該插件設定裏添加的 Chrome/Chromium 系和 Firefox 系瀏覽器配置檔案裏的書籤與歷史記錄。</td></tr><tr><td><code>set</code></td><td>核心擴展</td><td>應用內的每一項設定，按名稱模糊匹配——選中一項即可直接跳轉到設定裏對應的那一行並高亮。只打 <code>set</code> 不加任何內容會列出所有設定。</td></tr></tbody></table><p>視窗切換器預設會把每個視窗實際內容的實時縮略圖作為圖示——截圖在後臺進行，不會拖慢輸入速度：先立即顯示程式圖示，縮略圖準備好之後再補上。在<strong>設定 → 插件 → 視窗切換器 → 配置</strong>裏關掉&quot;用視窗內容作為圖示&quot;就能完全跳過這部分截圖，始終用程式圖示。真正的獨佔全屏視窗(大多數遊戲預設用的其實是無邊框視窗化，這種沒問題)截不到內容，會自動回退到程式圖示。</p><p>瀏覽器資料插件的書籤和歷史記錄是各自獨立索引的——<strong>索引書籤</strong>和<strong>索引歷史記錄</strong>是<strong>設定 → 插件 → 瀏覽器資料 → 配置</strong>裏兩個獨立的開關，所以你可以只關掉歷史記錄(它通常比書籤多得多)而繼續搜尋書籤，反過來也一樣。</p><h2 id="網頁搜尋" tabindex="-1">網頁搜尋 <a class="header-anchor" href="#網頁搜尋" aria-label="Permalink to &quot;網頁搜尋&quot;">​</a></h2><p>網頁搜尋插件自帶了幾個引擎/網站的預設關鍵詞——<code>bd</code>(百度)、<code>g</code>(谷歌)、<code>bing</code>(必應)、<code>gh</code> (GitHub)、<code>wiki</code>(維基百科)、<code>yt</code>(YouTube)——你也可以在<strong>設定 → 插件 → 網頁搜尋 → 配置</strong>裏完全自由地新增、編輯或刪除條目，每一條都有自己的名稱、關鍵詞、圖示和網址模板。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g lertaro github</span></span></code></pre></div><p>會在瀏覽器裏打開一次&quot;lertaro github&quot;的谷歌搜尋。</p><h2 id="檔案過濾器" tabindex="-1">檔案過濾器 <a class="header-anchor" href="#檔案過濾器" aria-label="Permalink to &quot;檔案過濾器&quot;">​</a></h2><p>在<strong>設定 → 插件 → 檔案過濾器 → 配置</strong>裏，為特定資料夾單獨建立索引規則。每條規則都有自己的 <strong>監控資料夾列表</strong>(遞歸掃描)、一個<strong>匹配後綴</strong>欄位(例如 <code>*.exe;*.lnk</code>——支援用 <code>;</code> 或 <code>,</code> 分隔多個模式，全部都會被匹配；預設的 <code>*</code> 匹配所有檔案)，以及一個可選的<strong>過濾器名稱</strong>，會顯示在結果的描述裏。子資料夾永遠會被收錄，不受匹配後綴影響——匹配後綴只過濾檔案。</p><p>給規則加上<strong>觸發關鍵字</strong>，可以把它的結果收在一個前綴關鍵詞後面(和上面的內置關鍵詞一樣)，而不是始終混在通用索引結果裏參與排序。</p><h2 id="完全自訂-關鍵詞你說了算" tabindex="-1">完全自訂(關鍵詞你說了算) <a class="header-anchor" href="#完全自訂-關鍵詞你說了算" aria-label="Permalink to &quot;完全自訂(關鍵詞你說了算)&quot;">​</a></h2><h3 id="自訂命令" tabindex="-1">自訂命令 <a class="header-anchor" href="#自訂命令" aria-label="Permalink to &quot;自訂命令&quot;">​</a></h3><p>定義你自己的 <code>&lt;關鍵詞&gt; &lt;參數&gt;</code> 命令，用來啓動一個外部程式，全部在<strong>設定 → 插件 → 自訂命令 → 配置</strong>裏配置。命令的參數模板支援位置佔位符(<code>%s1</code>、<code>%s2</code>……對應每個用空格分隔的參數)，以及一個 &quot;剩餘全部內容&quot;佔位符(<code>%s</code>，代表關鍵詞之後你輸入的所有內容)。</p><p>每條命令還有一個<strong>在快速導航中顯示</strong>勾選框(預設關閉)——打開後，這條命令會額外作為一個條目出現在<a href="./hotkeys.html#快速導航-滑鼠">快速導航</a>選單的根層級，不用打關鍵詞也能點開執行。<strong>快速導航子選單</strong> 欄位可以把它歸到某個具名子選單下，而不是直接放根層級——用 <code>/</code> 可以嵌套多級(比如&quot;工具/網絡&quot;代表兩級子選單);留空則保持在根層級。以這種方式執行時，命令會按配置好的參數原樣運行，因為這裏沒有打字輸入的參數內容可以代入 <code>%s1</code>/<code>%s</code>。</p><hr><p>本頁提到的插件都不是必需的——每一個都可以在<a href="./settings/plugins.html">設定 → 插件</a>裏單獨禁用，如果你不想讓它佔用鍵盤輸入的注意力;而<a href="./search-syntax.html">搜尋語法</a>介紹的是另一套始終生效、用於檔案/ 資料夾/應用程式搜尋的模糊查詢語言，和本頁內容是兩回事。</p>`,33)])])}const u=e(s,[["render",r]]);export{g as __pageData,u as default};
